        lines.append(f"unsupported (file-level only): {report.unsupported} files")
    if report.case_collisions:
        groups = tuple(" = ".join(group) for group in report.case_collisions)
        lines.append(f"case collisions: {_paths(groups)}")
    return "\n".join(lines)


